#!/usr/bin/env python3
"""S-b: wrapper-normalised comparison of the definition region.
Extract from `variable {n : ℕ}` through the end of NavierStokesExistenceAndSmoothnessPeriodic
(the last shared declaration), then strip ONLY: `, category API, AMS 35` inside attributes,
standalone `@[category API, AMS 35]` lines, and the `local ` prefix on notation.
Anything left in the diff is NOT wrapper."""
import re, sys, difflib

def region(path):
    lines = open(path, encoding='utf-8').read().split('\n')
    start = next(i for i, l in enumerate(lines) if l.startswith('variable {n : ℕ}'))
    end = next(i for i, l in enumerate(lines) if l.startswith('  isOnePeriodic_pressure'))
    out = []
    for l in lines[start:end + 1]:
        if l.strip() == '@[category API, AMS 35]':
            continue
        l = l.replace('@[simp, category API, AMS 35]', '@[simp]')
        l = re.sub(r'^local notation', 'notation', l)
        out.append(l)
    return out

up = region(sys.argv[1])
for other in sys.argv[2:]:
    o = region(other)
    d = list(difflib.unified_diff(up, o, fromfile=sys.argv[1], tofile=other, lineterm=''))
    print(f"== {other}: region lines up={len(up)} other={len(o)} residual diff lines={len(d)}")
    print('\n'.join(d) if d else '(IDENTICAL after wrapper normalisation)')

def thm(path):
    src = open(path, encoding='utf-8').read()
    out = {}
    for name in ('navier_stokes_breakdown_R3', 'navier_stokes_breakdown_periodic'):
        m = re.search(r'^theorem ' + name + r'.*?:= by', src, re.S | re.M)
        out[name] = re.sub(r'\s+', ' ', m.group(0)) if m else None
    return out

ref = thm(sys.argv[1])
for other in sys.argv[2:] + sys.argv[-1:]:
    pass
print("== theorem statements (whitespace-collapsed) equal to upstream?")
for other in sys.argv[2:]:
    t = thm(other)
    for k in ref:
        print(f"  {other.split('/')[-1]} {k}: {'MISSING (not stated in this file)' if t[k] is None else ('EQUAL' if t[k]==ref[k] else 'DIFFERENT: '+t[k])}")
